import numpy as np
vocab=["up","down","flat"]
trans=np.log(np.array([[.7,.2,.1],[.2,.6,.2],[.3,.3,.4]]))
beam=[([0],0.)]
for _ in range(3):
    candidates=[]
    for seq,score in beam:
        for j in range(3):candidates.append((seq+[j],score+trans[seq[-1],j]))
    beam=sorted(candidates,key=lambda x:x[1],reverse=True)[:2]
print("Top sequences:",[([vocab[i] for i in seq],score) for seq,score in beam])

from bisect import bisect_right
times=[1,4,7];values=[.2,.3,.5]
def asof(t):
    j=bisect_right(times,t)-1
    return values[j] if j>=0 else None
for t in [0,3,5,9]:print(t,asof(t))
